function leapsBefore(y) {
  const p = y - 1;
  return Math.floor(p / 4) - Math.floor(p / 100) + Math.floor(p / 400);
}

function yearStart(y) {
  return 365 * (y - 1970) + leapsBefore(y) - leapsBefore(1970);
